import json
from pathlib import Path
from html import escape as h

root=Path(__file__).parent
live=json.loads((root/'resultados.json').read_text(encoding='utf-8'))
isolated=json.loads((root/'admin-aislado.json').read_text(encoding='utf-8'))
feedback=json.loads((root/'feedback-aislado.json').read_text(encoding='utf-8'))
# El texto vigente habla de la web institucional, no de una página interna de documentos.
for item in live['results']:
    if item['name']=='Alternativa al chat desde consentimiento':
        item['details']='El aviso menciona la web institucional y las dependencias como alternativas, pero no ofrece un enlace directo desde el diálogo.'
findings=[
dict(id='F01',p='P1',title='Adjuntar funciona visualmente, pero el backend descarta el archivo',proof='Selección, vista previa y retirada reales correctas. Al instanciar ChatRequest con attachments, model_dump() no conserva el campo: no está declarado en el contrato.',impact='Una persona puede creer que Yachi leyó su PDF o imagen cuando solo está respondiendo al texto.',fix='Conectar carga, límites y recuperación del archivo con el backend; mientras no exista esa capacidad, deshabilitar el envío de adjuntos y explicarlo.',source='api/app/main.py · ChatRequest; web/src/components/Composer.tsx; web/src/lib/api.ts · streamChat',kind='Prueba real de frontend + contrato Python ejecutado sin red'),
dict(id='F02',p='P1',title='Importar CSV de validación no actualiza el set del servidor',proof='La interfaz dice «Se cargaron 1 preguntas de control», pero la prueba registra cero peticiones para persistirlas. replaceControlSet y controlSize operan sobre mock.controlSet incluso con API configurada.',impact='La cantidad mostrada y las preguntas importadas pueden no coincidir con las que evalúa el backend.',fix='Obtener el set desde la API, persistir la importación y confirmar el número real antes de evaluar.',source='web/src/lib/api.ts · controlSize/replaceControlSet; web/src/views/AdminExtras.tsx · importCsv',kind='Reproducido con API aislada + revisión de código'),
dict(id='F03',p='P1',title='Feedback muestra éxito aunque el servidor responda con error',proof='Con HTTP 503 simulado, sigue apareciendo «Gracias. El equipo de la universidad revisará esta respuesta». sendFeedback no comprueba response.ok y el panel confirma antes del guardado.',impact='Se puede perder una alerta sobre información incorrecta mientras se promete que será revisada.',fix='Esperar confirmación, comprobar el código HTTP y ofrecer Reintentar; no mostrar éxito hasta guardar.',source='web/src/lib/api.ts · sendFeedback; web/src/components/Feedback.tsx · FeedbackPanel',kind='Error HTTP reproducido en aislamiento'),
dict(id='F04',p='P1',title='La consulta a una dependencia se registra, pero falta cerrar el circuito de atención',proof='El handler /inquiries inserta en la base y devuelve un código. No realiza un envío en ese handler. No se encontró una pantalla de gestión de estas consultas entre las ocho secciones del portal.',impact='El usuario obtiene un código sin una vía de atención visible para el personal en esta aplicación.',fix='Implementar una bandeja y/o notificaciones con estados y responsables. Hasta entonces describirlo como registro de consulta, sin prometer entrega ni respuesta.',source='api/app/main.py · inquiries; web/src/components/ProcedureCard.tsx · InquiryForm; web/src/views/Admin.tsx · tabs',kind='Hallazgo de código y navegación; no se envió una consulta real'),
dict(id='F05',p='P2',title='La evaluación queda bloqueada si falla la API',proof='Con HTTP 503, el botón permanece deshabilitado como «Evaluando» y se produce un rechazo no controlado. run no usa catch/finally.',impact='Es necesario abandonar o recargar la pantalla para volver a intentar.',fix='Mostrar un error legible y restaurar el estado en finally; manejar también errores al cargar inventario y bandeja.',source='web/src/views/AdminExtras.tsx · Validation.run; admin-aislado.json',kind='Reproducido con fallo de red simulado'),
dict(id='F06',p='P2',title='El inicio recorta el saludo cuando falta altura',proof='Con scroll del inicio en cero: a 320×568 el saludo empieza en y≈−44 px, y a 390×400 en y≈−95 px; el área empieza en y=56. A 390×844 sí queda visible.',impact='Parte del contenido queda por encima del área de lectura; puede empeorar con el teclado abierto.',fix='Usar centrado seguro o alinear arriba cuando el contenido supere el alto. Validar después con teclado real en móvil.',source='web/src/styles.css · .hello; resultados.json; inicio-320x568.png',kind='Medición real del DOM en tres viewports'),
dict(id='F07',p='P2',title='El formulario Subir se desborda en móvil',proof='Con datos aislados, la vista Subir alcanza 674 px de ancho en un viewport de 390 px. Las otras siete secciones se mantuvieron en 390 px durante esta prueba.',impact='Campos y acciones quedan fuera del ancho de pantalla.',fix='Revisar min-width de grids, campos y zona de carga; romper nombres largos y probar 320/390 px con y sin archivo.',source='web/src/views/Admin.tsx · Upload; web/src/styles.css · .form-grid; simulado-movil-subir.png',kind='Medición de frontend con API simulada'),
dict(id='F08',p='P2',title='El menú móvil no cierra con Escape ni aísla el fondo',proof='Escape deja rail-open-mobile activo y main.chat no es inert. El menú no tiene cierre visible propio ni manejo modal completo de foco.',impact='La navegación por teclado puede acceder al fondo mientras el lateral está abierto.',fix='Añadir cierre, Escape, foco dentro del menú, fondo inerte y retorno al botón que lo abrió.',source='web/src/views/Chat.tsx · mobileRail; resultados.json',kind='Prueba real de teclado + inspección del DOM'),
dict(id='F09',p='P2',title='La calculadora acepta una tasa de caché fuera del rango indicado',proof='El campo 0–1 acepta −2. El código aplica Math.min(1, valor), sin limitar el mínimo; el cálculo usa ese valor.',impact='Produce estimaciones incoherentes si el usuario escribe o pega valores negativos.',fix='Limitar a [0,1], validar el resto de supuestos y señalar entradas inválidas.',source='web/src/views/AdminExtras.tsx · Cost; admin-aislado.json',kind='Reproducido en calculadora local'),
dict(id='F10',p='P3',title='La primera visita no facilita la alternativa al consentimiento',proof='La bienvenida y el aviso funcionan. El diálogo menciona opciones externas, pero no proporciona un enlace directo a la web institucional; tampoco hay una acción alternativa explícita junto a aceptar.',impact='Quien decide no usar el chat queda sin un camino inmediato dentro del diálogo.',fix='Añadir un enlace institucional verificado y una salida clara. Revisar el texto final con el responsable institucional.',source='web/src/components/ConsentDialog.tsx; 01-bienvenida.png',kind='Navegación real y revisión de contenido; no es evaluación legal'),
dict(id='F11',p='P3',title='La composición todavía tiene decisiones visuales mejorables',proof='Las sugerencias pueden quedar 3+1 en escritorio, existen dos accesos de voz con propósitos distintos y las ocho secciones administrativas dependen de una fila desplazable en móvil.',impact='Jerarquía menos clara, repetición de temas y secciones difíciles de descubrir.',fix='Mantener la identidad actual; equilibrar tarjetas, distinguir Dictar/Conversar y evaluar navegación administrativa adaptable. Esto requiere decisión de diseño, no una sustitución automática.',source='web/src/styles.css; web/src/components/Composer.tsx; web/src/views/Admin.tsx',kind='Evaluación heurística, no defecto funcional demostrado'),
]
(root/'hallazgos.json').write_text(json.dumps(findings,ensure_ascii=False,indent=2),encoding='utf-8')
all_results=live['results']+isolated['results']
counts={s:sum(r['status']==s for r in all_results) for s in sorted({r['status'] for r in all_results})}
style='''*{box-sizing:border-box}body{margin:0;background:#f5f7fa;color:#182b3b;font:15px/1.65 system-ui,sans-serif}main{max-width:1100px;margin:auto;padding:40px 28px}h1{font-size:36px;line-height:1.2;margin:8px 0 18px}h2{font-size:24px;margin:32px 0 14px}h3{font-size:18px;margin:8px 0 12px}p{margin:8px 0}a{color:#27618e}.box,article{padding:23px;background:white;border:1px solid #dce3eb;border-radius:12px;margin:14px 0}.badge{display:inline-block;background:#e6eff6;border-radius:6px;padding:3px 9px;font-size:12px;font-weight:700}.P1{border-left:4px solid #b53c36}.P2{border-left:4px solid #c38a29}.P3{border-left:4px solid #27618e}small{color:#526676}table{width:100%;border-collapse:collapse;font-size:13px}th,td{border-bottom:1px solid #dce3eb;text-align:left;padding:12px;vertical-align:top}th{background:#edf2f7}.scroll{overflow:auto}pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}details summary{cursor:pointer;font-weight:600}.gallery{display:grid;grid-template-columns:1fr 1fr;gap:16px}.gallery img{width:100%;height:270px;object-fit:contain;background:#edf2f7;border:1px solid #dce3eb}figure{margin:0}figcaption{font-size:12px;color:#526676}button{font:inherit;background:#27618e;color:white;border:0;border-radius:8px;padding:10px 16px;cursor:pointer}@media(max-width:650px){main{padding:24px 16px}.gallery{grid-template-columns:1fr}h1{font-size:29px}}@media print{body{background:white}main{padding:0;max-width:none}article,.box{break-inside:avoid}button{display:none}.gallery img{height:200px}h2{break-after:avoid}}'''
parts=[f'<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Yachi · Auditoría integral</title><style>{style}</style><main>',
'<small>IDEATHON · 20 OCTUBRE 2026 · CHROME / PLAYWRIGHT</small><h1>Auditoría funcional y de diseño de Yachi</h1>',
'<p>El chat público funciona en sus recorridos principales. Los riesgos más importantes están en capacidades que parecen conectadas pero no completan su circuito: adjuntos, importación de validación, feedback y atención por dependencia.</p>',
'<div class="box"><b>Cambio aplicado:</b> «Ver lo más reciente» ahora usa una flecha hacia abajo. El pulgar queda reservado al voto negativo. El resto de hallazgos se presenta para revisión; no se ha rediseñado ni modificado masivamente la aplicación.</div>',
'<h2>Alcance y límites</h2><div class="box"><p>Se recorrieron primera visita, inicio, idiomas, temas, historial, fuentes, mapa, aclaraciones, datos personales, diálogos, voz y widget contra el servicio local. Se probaron escritorio 1440×1000 y móvil 390×844, 320×568 y espacio reducido 390×400.</p><p>El primer intento administrativo real devolvió HTTP 429. No se insistió ni se eludió el límite. Las ocho secciones administrativas se recorrieron con endpoints interceptados y datos sintéticos: valida interfaz y conexiones de botones, no autenticación, persistencia, subida ni procesamiento reales.</p><p>Los datos de prueba y credenciales no se publicaron. No se subieron ni borraron documentos reales, no se alteraron filtros reales ni se enviaron consultas a dependencias. Las preguntas públicas de prueba sí recorren el backend y pueden quedar en su registro normal.</p><p>No es certificación de accesibilidad ni auditoría de seguridad. Sin axe disponible no se ejecutó un escaneo axe. No se probó lector de pantalla, micrófono real, reconocimiento/síntesis completos, selector de captura del sistema, Safari/iOS, envío real de correo ni tarifas actuales de proveedores. La configuración revisada no tiene clave del modelo: las respuestas redactadas por IA no se validaron de extremo a extremo.</p></div>',
'<h2>Resumen de comprobaciones</h2><p>'+h(json.dumps(counts,ensure_ascii=False))+' · Los conteos incluyen subpruebas y modos diferentes; no son un porcentaje de calidad ni de cobertura de líneas.</p>',
'<div class="scroll"><table><tr><th>Área</th><th>Qué se comprobó</th><th>Resultado</th></tr>']
coverage=[
('Inicio y consentimiento','Abrir, desplegar aviso, aceptar, temas claro/oscuro, idiomas y Kichwa beta','Funciona; mejorar alternativa y pantallas bajas.'),
('Chat conectado','Pregunta real, respuesta extractiva, fuente con detalle y actividad','Funciona; exactitud de todo el corpus y generación con modelo fuera del alcance.'),
('Historial','Renombrar, eliminar y deshacer','Funciona; se comprobó contraste del aviso.'),
('Aclaraciones y mapa','Consulta ambigua y biblioteca','Funcionan los recorridos probados; el mapa y sus dependencias estaban recibiendo cambios durante la auditoría.'),
('Fuera de ámbito','Una primera pasada obtuvo tarjeta de rechazo; la segunda no','No se declara fallo confirmado: requiere aislar intención/historial y reproducir.'),
('Adjuntos','Seleccionar, ampliar y retirar imagen; contrato del backend','Interfaz funciona; contrato descarta el archivo.'),
('Voz','Ruta directa, configuración y Escape','Parcial; falta hardware y permisos reales.'),
('Widget','Avatar, abrir, cerrar y panel móvil','Funciona en el recorrido probado.'),
('Administración','Acceso real','Bloqueado por HTTP 429; no es prueba de contraseña incorrecta ni de caída.'),
('Documentos/Subir','Buscar, estado vacío, formulario, envío multipart y reprocesar','Conexiones de UI verificadas con API simulada; persistencia/ingesta reales pendientes.'),
('Temas/Tendencias/Sin respuesta','Apertura y renderizado','Verificados con datos de prueba; creación, descartes y conversiones reales pendientes.'),
('Filtros','Probar frase y ejecutar casos','Botones y métricas con respuestas simuladas; reglas reales no certificadas por este recorrido.'),
('Validación','Importar, ejecutar, exportar y fallo 503','Se detectan importación no persistida y bloqueo al fallar.'),
('Costo','Cambio de supuestos y valores límite','Se actualiza, pero admite caché negativa; precios y modelo de costo no contrastados.'),
('Feedback/Dependencias','Fallo al guardar feedback y revisión del handler de consultas','Éxito falso del feedback reproducido; circuito de atención incompleto por inspección.'),
]
for a,b,c in coverage:parts.append(f'<tr><td>{h(a)}</td><td>{h(b)}</td><td>{h(c)}</td></tr>')
parts.append('</table></div><h2>Hallazgos priorizados</h2>')
for f in findings:
    parts.append(f'<article class="{f["p"]}"><span class="badge">{f["id"]} · {f["p"]}</span><h3>{h(f["title"])}</h3><p><b>Evidencia:</b> {h(f["proof"])}</p><p><b>Consecuencia:</b> {h(f["impact"])}</p><p><b>Recomendación:</b> {h(f["fix"])}</p><small>{h(f["kind"])}<br>{h(f["source"])}</small></article>')
parts.append('<h2>Capturas de evidencia</h2><div class="gallery">')
for f,label in [('02-inicio.png','Inicio real'),('05-chat-real.png','Respuesta y fuente reales'),('inicio-320x568.png','Inicio con altura reducida'),('simulado-movil-subir.png','Subir en móvil · API simulada'),('simulado-validacion.png','Validación · API simulada'),('06-voz.png','Pantalla de voz')]:
    if (root/f).exists():parts.append(f'<figure><a href="{f}"><img src="{f}" alt="{h(label)}"></a><figcaption>{h(label)}</figcaption></figure>')
parts.append('</div><h2>Orden recomendado</h2><div class="box"><ol><li>Corregir los circuitos de adjuntos, validación, feedback y atención por dependencia antes de prometerlos.</li><li>Recuperación de errores y confirmaciones de guardado.</li><li>Corregir inicio bajo, subida móvil y menú con teclado.</li><li>Validar límites de calculadora y afinar la jerarquía visual con el usuario.</li><li>Repetir administración con sesión válida y documento temporal controlado; probar voz/captura con hardware y un lector de pantalla.</li></ol></div>')
parts.append('<h2>Registro de pruebas</h2><p><a href="resultados.json">Pruebas conectadas</a> · <a href="admin-aislado.json">Administración aislada</a> · <a href="feedback-aislado.json">Feedback aislado</a> · <a href="hallazgos.json">Hallazgos estructurados</a></p>')
for label,data in [('Con servicio local',live['results']),('Con API simulada',isolated['results'])]:
    parts.append(f'<details class="box"><summary>{label}</summary><table><tr><th>Prueba</th><th>Estado</th><th>Detalle</th></tr>')
    for r in data:parts.append(f'<tr><td>{h(r["name"])}</td><td>{h(r["status"])}</td><td><pre>{h(json.dumps(r["details"],ensure_ascii=False,indent=2))}</pre></td></tr>')
    parts.append('</table></details>')
parts.append('<p><button onclick="window.print()">Imprimir / guardar PDF</button></p></main></html>')
(root/'index.html').write_text(''.join(parts),encoding='utf-8')
print('Informe generado:',len(findings),'hallazgos.',len(all_results),'comprobaciones registradas.')
